  display: flex;
  flex-wrap: wrap;
  padding-left: 0;
  list-style: none;
}
.cmp-tabs__tab {
  box-sizing: border-box;
  border-bottom: 1px solid transparent;
  padding: .5rem 1rem;
  cursor: pointer;
}
.cmp-tabs__tab--active {
  border-color: inherit;
}
